from pathlib import Path
import csv

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "results" / "q7_performance.csv"

# Simplified illustrative model to demonstrate metrics across mobility levels.
# Values are generated by this model; they are not measured radio/network results.
scenarios = [
    {"scenario": "Low mobility", "sent": 100, "received": 98, "avg_delay_ms": 35, "control_packets": 20},
    {"scenario": "Medium mobility", "sent": 100, "received": 93, "avg_delay_ms": 58, "control_packets": 34},
    {"scenario": "High mobility", "sent": 100, "received": 82, "avg_delay_ms": 105, "control_packets": 61},
    {"scenario": "Link failure and repair", "sent": 100, "received": 76, "avg_delay_ms": 142, "control_packets": 75},
]

for row in scenarios:
    row["packet_delivery_ratio_percent"] = round(row["received"] / row["sent"] * 100, 2)
    row["routing_overhead_ratio"] = round(row["control_packets"] / row["received"], 3)

with OUT.open("w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=scenarios[0].keys())
    writer.writeheader()
    writer.writerows(scenarios)

print("Q7 emergency network — illustrative model output")
for row in scenarios:
    print(row)
print("Metrics:")
print("PDR (%) = packets received / packets sent * 100")
print("Routing overhead ratio = routing-control packets / data packets received")
print("Average delay is a model input for this demonstration.")
print("These values are illustrative, not real measured simulation results.")
print(f"CSV saved to {OUT.relative_to(ROOT)}")
